CREATE TABLE public.account_consents (user_id uuid PRIMARY KEY, legal_version text, accepted_at timestamptz, founding_member boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_consents TO authenticated;
GRANT ALL ON public.account_consents TO service_role;
ALTER TABLE public.account_consents ENABLE ROW LEVEL SECURITY;
CREATE POLICY account_consents_own_read ON public.account_consents FOR SELECT TO authenticated USING (user_id=auth.uid());
ALTER TABLE public.app_settings ADD COLUMN founding_open boolean NOT NULL DEFAULT true, ADD COLUMN founding_closed_at timestamptz;
ALTER TABLE public.trips ALTER COLUMN level SET DEFAULT 'full';
CREATE OR REPLACE FUNCTION trip_private.account_status() RETURNS TABLE(legal_version text, accepted_at timestamptz, founding_member boolean, founding_open boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.legal_version,c.accepted_at,coalesce(c.founding_member,false),coalesce(s.founding_open,false) FROM public.app_settings s LEFT JOIN public.account_consents c ON c.user_id=auth.uid() WHERE auth.uid() IS NOT NULL LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.account_status() RETURNS TABLE(legal_version text, accepted_at timestamptz, founding_member boolean, founding_open boolean) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT * FROM trip_private.account_status() $$;
CREATE OR REPLACE FUNCTION trip_private.accept_legal(p_version text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_created timestamptz; v_open boolean; v_closed timestamptz; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF p_version <> '2026-10-04' THEN RAISE EXCEPTION 'Please review the current terms'; END IF; SELECT created_at INTO v_created FROM auth.users WHERE id=auth.uid(); SELECT founding_open,founding_closed_at INTO v_open,v_closed FROM public.app_settings LIMIT 1; INSERT INTO public.account_consents(user_id,legal_version,accepted_at,founding_member) VALUES(auth.uid(),p_version,now(),coalesce(v_open,false) OR (v_closed IS NOT NULL AND v_created < v_closed)) ON CONFLICT(user_id) DO UPDATE SET legal_version=excluded.legal_version,accepted_at=excluded.accepted_at,updated_at=now(),founding_member=public.account_consents.founding_member OR excluded.founding_member; END $$;
CREATE OR REPLACE FUNCTION public.accept_legal(p_version text) RETURNS void LANGUAGE sql SET search_path=public AS $$ SELECT trip_private.accept_legal(p_version) $$;
CREATE OR REPLACE FUNCTION trip_private.set_founding_open(p_open boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF; IF p_open IS NULL THEN RAISE EXCEPTION 'Choose open or closed'; END IF; UPDATE public.app_settings SET founding_open=p_open,founding_closed_at=CASE WHEN p_open THEN NULL ELSE coalesce(founding_closed_at,now()) END; END $$;
CREATE OR REPLACE FUNCTION public.set_founding_open(p_open boolean) RETURNS void LANGUAGE sql SET search_path=public AS $$ SELECT trip_private.set_founding_open(p_open) $$;
CREATE OR REPLACE FUNCTION trip_private.ai_daily_counts() RETURNS TABLE(day date,user_id uuid,calls bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT trip_private.is_app_admin() THEN RAISE EXCEPTION 'Founder only'; END IF; RETURN QUERY SELECT (u.created_at AT TIME ZONE 'UTC')::date,u.user_id,count(*) FROM public.ai_usage u WHERE u.created_at>=now()-interval '30 days' GROUP BY 1,2 ORDER BY 1 DESC,3 DESC; END $$;
CREATE OR REPLACE FUNCTION public.ai_daily_counts() RETURNS TABLE(day date,user_id uuid,calls bigint) LANGUAGE sql STABLE SET search_path=public AS $$ SELECT * FROM trip_private.ai_daily_counts() $$;
REVOKE ALL ON FUNCTION trip_private.account_status(),trip_private.accept_legal(text),trip_private.set_founding_open(boolean),trip_private.ai_daily_counts(),public.account_status(),public.accept_legal(text),public.set_founding_open(boolean),public.ai_daily_counts() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION trip_private.account_status(),trip_private.accept_legal(text),trip_private.set_founding_open(boolean),trip_private.ai_daily_counts(),public.account_status(),public.accept_legal(text),public.set_founding_open(boolean),public.ai_daily_counts() TO authenticated;